function conflict(code: string, message: string): RuntimeRpcFailureError {
  return new RuntimeRpcFailureError({
    id: 'request-1',
    ok: false,
    error: { code, message: `${message}: ${code}` },
    _meta: { runtimeId: 'runtime-1' }
  })
}

